using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using Cysharp.Threading.Tasks;
using MiniFramework.Contracts;
using MiniFramework.Runtime;
using MiniFramework.Storage;
using MiniFramework.Providers.StorageFake;
using NUnit.Framework;
using UnityEngine.TestTools;
public sealed class StorageRecoveryTests
{
    static OperationContext Wait=>OperationContext.Unlimited();static CleanupContext Cleanup=>new CleanupContext(default,Timeout.InfiniteTimeSpan);
    static readonly StorageAddress Address=new StorageAddress("local","main");sealed class Data{}
    sealed class Consumer:IModule
    {
        readonly Env env;public Consumer(Env e){env=e;}public string Id=>"consumer";public IReadOnlyList<string> Dependencies=>new[]{"storage"};
        public UniTask<Result> InitializeAsync(IModuleContext context,OperationContext operation)
        {if(!context.Services.TryGet<IStorageRecoveryService>(out var storage)||storage.Restored==null)return UniTask.FromResult(Result.Failure(new FrameworkError(ErrorKind.NotReady,"test.restore")));if(!storage.Restored.IsNew)env.Value=storage.Restored.Read("progress").Value[0];return UniTask.FromResult(Result.Success());}
        public UniTask<Result> StopAsync(CleanupContext cleanup)=>UniTask.FromResult(Result.Success());public UniTask<Result> DisposeAsync(CleanupContext cleanup)=>UniTask.FromResult(Result.Success());
    }
    sealed class Env
    {
        internal readonly FakeStorageStore Store;internal readonly FakeStorageProvider Provider;internal readonly StorageService Service;internal readonly GameContext Context;
        internal byte Value=1;internal bool Invalid;
        internal Env(FakeStorageStore store=null,int target=3,bool migrate=true,bool holdReads=false,bool holdWrites=false,bool consumer=false,Func<byte[],Result<byte[]>> second=null)
        {
            Store=store??new FakeStorageStore();Provider=new FakeStorageProvider(Store){HoldReads=holdReads,HoldCommits=holdWrites};
            var registry=new StorageRegistry();registry.Register(new StorageModuleRegistration("progress",target,"bytes-v"+target,true,typeof(Data),()=>Result<byte[]>.Success(new byte[]{Value,0,9}.Take(target).ToArray()),b=>Invalid||b.Length!=target?Result.Failure(new FrameworkError(ErrorKind.Integrity,"test.invalid")):Result.Success()));
            var migrations=new StorageMigrationRegistry();
            if(migrate){migrations.Register(new StorageMigrationStep("progress",1,"bytes-v1","bytes-v2",b=>Result<byte[]>.Success(b.Concat(new byte[]{0}).ToArray())));migrations.Register(new StorageMigrationStep("progress",2,"bytes-v2","bytes-v3",second??(b=>Result<byte[]>.Success(b.Concat(new byte[]{9}).ToArray()))));}
            Service=new StorageService(Provider,Address,registry,recovery:new StorageRecovery(migrations));
            var registrations=new List<ModuleRegistration>{new ModuleRegistration("storage",Array.Empty<string>(),()=>Service,typeof(IStorageService),typeof(IStorageRecoveryService))};
            if(consumer)registrations.Add(new ModuleRegistration("consumer",new[]{"storage"},()=>new Consumer(this)));
            Context=new GameContext(registrations,Cleanup);
        }
        internal async UniTask Start(){Check(await Context.StartAsync(Wait));}
        internal async UniTask<Result<StorageCommitReceipt>> Save(){var captured=Service.Capture();Assert.IsTrue(captured.IsSuccess);return await captured.Value.WaitAsync(Wait);}
        internal FakeStorageSession Session=>Provider.Sessions[0];
        internal async UniTask Finish()
        {
            Store.FailRead=Store.FailCleanup=false;foreach(var s in Provider.Sessions){s.CompleteRead();while(s.CompleteNextCommit()){};}
            var closing=Context.CloseAsync(Wait);for(var i=0;i<5;i++){foreach(var s in Provider.Sessions)while(s.CompleteNextCommit()){};await UniTask.Yield();}
            var result=await closing;if(!result.IsSuccess)result=await Context.RetryCleanupAsync(Cleanup,Wait);Check(result);Assert.AreEqual(0,Context.RetainedModuleCount);
        }
    }
    readonly List<Env> envs=new List<Env>();
    Env New(FakeStorageStore store=null,int target=3,bool migrate=true,bool holdReads=false,bool holdWrites=false,bool consumer=false,Func<byte[],Result<byte[]>> second=null){var e=new Env(store,target,migrate,holdReads,holdWrites,consumer,second);envs.Add(e);return e;}
    static FakeStorageStore Saved(int schema=1,bool optional=true)
    {var store=new FakeStorageStore();var rows=new List<StorageRecord>{new StorageRecord("progress",schema,"bytes-v"+schema,true,new byte[]{7,0,9}.Take(schema).ToArray())};if(optional)rows.Add(new StorageRecord("addon",9,"opaque",false,new byte[]{201,202}));store.SeedRaw(Address,StorageFormat.Encode(new StorageContainer(Address,4,rows),new StorageLimits()).Value);return store;}
    static void Check(Result result)=>Assert.IsTrue(result.IsSuccess,result.IsSuccess?"":result.Error.Code);
    static async UniTask Frames(int n=3){for(var i=0;i<n;i++)await UniTask.Yield();}
    [UnityTearDown] public IEnumerator TearDown()=>UniTask.ToCoroutine(async()=>{foreach(var e in envs)await e.Finish();envs.Clear();});
    [UnityTest] public IEnumerator NewSlotPublishesEmptyWithoutWriting()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();Assert.IsTrue(e.Service.Restored.IsNew);Assert.AreEqual(0,e.Session.CommitCount);Assert.IsNull(e.Store.CopyRaw(Address));});
    [UnityTest] public IEnumerator CompatibleLoadPublishesWithoutRewriting()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(3));await e.Start();Assert.AreEqual(7,e.Service.Restored.Read("progress").Value[0]);Assert.AreEqual(0,e.Session.CommitCount);Assert.AreEqual(4,e.Service.Restored.Sequence);});
    [UnityTest] public IEnumerator TwoMigrationEdgesCommitOnlyOnceBeforePublication()=>UniTask.ToCoroutine(async()=>{var e=New(Saved());await e.Start();Assert.AreEqual(1,e.Session.CommitCount);Assert.AreEqual(5,e.Service.Restored.Sequence);CollectionAssert.AreEqual(new byte[]{7,0,9},e.Service.Restored.Read("progress").Value);});
    [UnityTest] public IEnumerator ContextConsumerRestoresModelBeforeCapture()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(),consumer:true);await e.Start();Assert.AreEqual(7,e.Value);Assert.IsTrue((await e.Save()).IsSuccess);Assert.AreEqual(7,StorageFormat.Decode(e.Store.CopyRaw(Address),new StorageLimits()).Value.Records.Single(r=>r.ModuleId=="progress").CopyPayload()[0]);});
    [UnityTest] public IEnumerator NewContextRestoresLastCommittedValue()=>UniTask.ToCoroutine(async()=>{var first=New(consumer:true);await first.Start();first.Value=42;await first.Save();Check(await first.Context.CloseAsync(Wait));var second=New(first.Store,consumer:true);await second.Start();Assert.AreEqual(42,second.Value);Assert.AreEqual(0,second.Session.CommitCount);});
    [UnityTest] public IEnumerator UnknownOptionalBytesSurviveMigrationAndNextSave()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(),consumer:true);await e.Start();await e.Save();var r=StorageFormat.Decode(e.Store.CopyRaw(Address),new StorageLimits()).Value.Records.Single(x=>x.ModuleId=="addon");Assert.AreEqual(9,r.SchemaVersion);Assert.AreEqual("opaque",r.CodecId);CollectionAssert.AreEqual(new byte[]{201,202},r.CopyPayload());});
    [UnityTest] public IEnumerator MissingMigrationKeepsOriginalAndPublishesNothing()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);var e=New(store,migrate:false);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(e.Service.Restored);CollectionAssert.AreEqual(old,store.CopyRaw(Address));Assert.AreEqual(0,e.Session.CommitCount);});
    [UnityTest] public IEnumerator MidChainThrowKeepsOriginal()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);var e=New(store,second:_=>throw new Exception());Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);CollectionAssert.AreEqual(old,store.CopyRaw(Address));Assert.IsNull(e.Service.Restored);Assert.AreEqual(0,e.Session.CommitCount);});
    [UnityTest] public IEnumerator FinalValidationFailureNeverWritesOrPublishes()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);var e=New(store);e.Invalid=true;Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.AreEqual(0,e.Session.CommitCount);CollectionAssert.AreEqual(old,store.CopyRaw(Address));Assert.IsNull(e.Service.Restored);});
    [UnityTest] public IEnumerator MigrationQuotaRejectionRetainsOldVersion()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);store.Faults.Enqueue(FakeStorageFault.Quota);var e=New(store);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);CollectionAssert.AreEqual(old,store.CopyRaw(Address));Assert.IsNull(e.Service.Restored);Assert.AreEqual(StorageCommitDisposition.Rejected,e.Service.LastReceipt.Disposition);});
    [UnityTest] public IEnumerator MigrationUnknownAfterWriteDoesNotPublishAndReopenReconciles()=>UniTask.ToCoroutine(async()=>{var store=Saved();store.Faults.Enqueue(FakeStorageFault.UnknownAfterWrite);var first=New(store);Assert.IsFalse((await first.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(first.Service.Restored);Assert.AreEqual(5,StorageFormat.Decode(store.CopyRaw(Address),new StorageLimits()).Value.Sequence);var second=New(store,consumer:true);await second.Start();Assert.AreEqual(7,second.Value);Assert.AreEqual(0,second.Session.CommitCount);});
    [UnityTest] public IEnumerator MigrationUnknownBeforeWriteRetainsOldBytes()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);store.Faults.Enqueue(FakeStorageFault.UnknownBeforeWrite);var e=New(store);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);CollectionAssert.AreEqual(old,store.CopyRaw(Address));Assert.IsNull(e.Service.Restored);});
    [UnityTest] public IEnumerator SnapshotStaysNullUntilActualMigrationCommit()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(),holdWrites:true);var start=e.Context.StartAsync(Wait);await Frames();Assert.IsNull(e.Service.Restored);Assert.AreEqual(StorageState.Loading,e.Service.State);e.Session.CompleteNextCommit();Check(await start);Assert.IsNotNull(e.Service.Restored);});
    [UnityTest] public IEnumerator CanceledMigrationObserverDrainsWithoutLatePublication()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(),holdWrites:true);using(var c=new CancellationTokenSource()){var start=e.Context.StartAsync(OperationContext.Unlimited(c.Token));await Frames();c.Cancel();Assert.AreEqual(ErrorKind.Canceled,(await start).Error.Kind);var close=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(0,e.Session.CleanupCount);e.Session.CompleteNextCommit();await close;Assert.IsNull(e.Service.Restored);Assert.AreNotEqual(StorageState.Ready,e.Service.State);Assert.AreEqual(5,StorageFormat.Decode(e.Store.CopyRaw(Address),new StorageLimits()).Value.Sequence);}});
    [UnityTest] public IEnumerator CanceledReadCannotStartLateMigrationWrite()=>UniTask.ToCoroutine(async()=>{var store=Saved();var old=store.CopyRaw(Address);var e=New(store,holdReads:true);using(var c=new CancellationTokenSource()){var start=e.Context.StartAsync(OperationContext.Unlimited(c.Token));await Frames();c.Cancel();await start;e.Session.CompleteRead();await e.Context.CloseAsync(Wait);Assert.AreEqual(0,e.Session.CommitCount);Assert.IsNull(e.Service.Restored);CollectionAssert.AreEqual(old,store.CopyRaw(Address));}});
    [UnityTest] public IEnumerator TimedOutReadCannotPublishOrMigrateLate()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(),holdReads:true);var start=e.Context.StartAsync(new OperationContext(default,TimeSpan.FromMilliseconds(1)));await UniTask.Delay(10,ignoreTimeScale:true);Assert.AreEqual(ErrorKind.Timeout,(await start).Error.Kind);e.Session.CompleteRead();await e.Context.CloseAsync(Wait);Assert.AreEqual(0,e.Session.CommitCount);Assert.IsNull(e.Service.Restored);});
    [UnityTest] public IEnumerator TwoContextsCannotBothMigrateSameOldVersion()=>UniTask.ToCoroutine(async()=>{var store=Saved();var a=New(store,holdWrites:true);var b=New(store,holdWrites:true);var sa=a.Context.StartAsync(Wait);var sb=b.Context.StartAsync(Wait);await Frames();a.Session.CompleteNextCommit();Check(await sa);b.Session.CompleteNextCommit();Assert.IsFalse((await sb).IsSuccess);Assert.IsNull(b.Service.Restored);Assert.AreEqual(5,StorageFormat.Decode(store.CopyRaw(Address),new StorageLimits()).Value.Sequence);});
    [UnityTest] public IEnumerator CorruptReadNeverPublishesOrWrites()=>UniTask.ToCoroutine(async()=>{var store=new FakeStorageStore();store.SeedRaw(Address,new byte[]{1,2});var e=New(store);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(e.Service.Restored);Assert.AreEqual(0,e.Session.CommitCount);CollectionAssert.AreEqual(new byte[]{1,2},store.CopyRaw(Address));});
    [UnityTest] public IEnumerator ReadFailureIsNotNewSlot()=>UniTask.ToCoroutine(async()=>{var store=new FakeStorageStore{FailRead=true};var e=New(store);Assert.IsFalse((await e.Context.StartAsync(Wait)).IsSuccess);Assert.IsNull(e.Service.Restored);Assert.IsNull(store.CopyRaw(Address));});
    [UnityTest] public IEnumerator FakeExplicitRejectionRetainsPriorCommittedData()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Save();var old=e.Store.CopyRaw(Address);e.Value=9;e.Store.Faults.Enqueue(FakeStorageFault.Reject);Assert.IsFalse((await e.Save()).IsSuccess);CollectionAssert.AreEqual(old,e.Store.CopyRaw(Address));Assert.AreEqual(1,e.Service.CommittedSequence);});
    [UnityTest] public IEnumerator FakeUnknownWriteLocksServiceUntilReopen()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Store.Faults.Enqueue(FakeStorageFault.UnknownAfterWrite);var op=e.Service.Capture().Value;Assert.IsFalse((await op.WaitAsync(Wait)).IsSuccess);Assert.IsTrue(op.CommitResult.RequiresReconciliation);Assert.AreEqual(StorageState.RecoveryRequired,e.Service.State);Assert.IsFalse(e.Service.Capture().IsSuccess);});
    [UnityTest] public IEnumerator FakeThrowBeforeWriteIsConservativelyUnknown()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Store.Faults.Enqueue(FakeStorageFault.ExceptionBeforeWrite);Assert.IsFalse((await e.Save()).IsSuccess);Assert.IsNull(e.Store.CopyRaw(Address));Assert.AreEqual(StorageState.RecoveryRequired,e.Service.State);});
    [UnityTest] public IEnumerator FakeThrowAfterWriteReopensCommittedVersion()=>UniTask.ToCoroutine(async()=>{var first=New();await first.Start();first.Value=31;first.Store.Faults.Enqueue(FakeStorageFault.ExceptionAfterWrite);Assert.IsFalse((await first.Save()).IsSuccess);await first.Context.CloseAsync(Wait);var second=New(first.Store,consumer:true);await second.Start();Assert.AreEqual(31,second.Value);});
    [UnityTest] public IEnumerator FakeQuotaAcrossSlotsKeepsExistingBytes()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();await e.Save();var old=e.Store.CopyRaw(Address);e.Store.QuotaBytes=old.Length-1;Assert.IsFalse((await e.Save()).IsSuccess);CollectionAssert.AreEqual(old,e.Store.CopyRaw(Address));});
    [UnityTest] public IEnumerator PublishedBytesCannotBeChangedByConsumer()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(3));await e.Start();var b=e.Service.Restored.Read("progress").Value;b[0]=99;Assert.AreEqual(7,e.Service.Restored.Read("progress").Value[0]);});
    [UnityTest] public IEnumerator StopClearsPublicSnapshotWithoutMutatingHeldValue()=>UniTask.ToCoroutine(async()=>{var e=New(Saved(3));await e.Start();var held=e.Service.Restored;Check(await e.Context.CloseAsync(Wait));Assert.IsNull(e.Service.Restored);Assert.AreEqual(7,held.Read("progress").Value[0]);});
    [UnityTest] public IEnumerator CleanupFailureRequiresExplicitRetry()=>UniTask.ToCoroutine(async()=>{var e=New();await e.Start();e.Store.FailCleanup=true;Assert.IsFalse((await e.Context.CloseAsync(Wait)).IsSuccess);Assert.AreEqual(1,e.Context.RetainedModuleCount);e.Store.FailCleanup=false;Check(await e.Context.RetryCleanupAsync(Cleanup,Wait));Assert.AreEqual(2,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator CancelingAcceptedSaveDoesNotDiscardActualBytes()=>UniTask.ToCoroutine(async()=>{var e=New(holdWrites:true);await e.Start();var op=e.Service.Capture().Value;using(var c=new CancellationTokenSource()){var save=op.WaitAsync(OperationContext.Unlimited(c.Token));c.Cancel();await Frames();Assert.AreEqual(ErrorKind.Canceled,(await save).Error.Kind);e.Session.CompleteNextCommit();await Frames();Assert.IsTrue(op.CommitResult.IsCommitted);Assert.IsFalse(op.CommitResult.IsRestartRecoverable);}});
    [UnityTest] public IEnumerator CloseWaitsForFakePendingWriteBeforeCleanup()=>UniTask.ToCoroutine(async()=>{var e=New(holdWrites:true);await e.Start();var save=e.Save();var closing=e.Context.CloseAsync(Wait);await Frames();Assert.AreEqual(0,e.Session.CleanupCount);e.Session.CompleteNextCommit();Check(await closing);Assert.IsTrue((await save).IsSuccess);Assert.AreEqual(1,e.Session.CleanupCount);});
    [UnityTest] public IEnumerator RepeatedReopenCyclesKeepRecoveredValueAndNoPendingWork()=>UniTask.ToCoroutine(async()=>{var store=new FakeStorageStore();for(var i=1;i<=10;i++){var e=New(store,consumer:true);await e.Start();Assert.AreEqual(i==1?1:i-1,e.Value);e.Value=(byte)i;await e.Save();Check(await e.Context.CloseAsync(Wait));Assert.AreEqual(0,e.Service.ReadDiagnostics().PendingOperations);}});
}
